BEGIN TRANSACTION;
CREATE TABLE contratado (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                nome TEXT NOT NULL,
                cep TEXT,
                logradouro TEXT,
                numero TEXT,
                bairro TEXT,
                cidade TEXT,
                uf TEXT,
                documento TEXT,
                email TEXT,
                celular TEXT,
                whatsapp TEXT,
                criado_em TEXT DEFAULT CURRENT_TIMESTAMP
            , foto_documento TEXT, foto_comprovante TEXT, contratante_id INTEGER);
CREATE TABLE contratante (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                nome TEXT NOT NULL,
                cep TEXT,
                logradouro TEXT,
                numero TEXT,
                bairro TEXT,
                cidade TEXT,
                uf TEXT,
                documento TEXT,
                email TEXT,
                celular TEXT,
                whatsapp TEXT,
                criado_em TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE contrato (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                numero TEXT UNIQUE NOT NULL,
                contratante_id INTEGER NOT NULL,
                contratado_id INTEGER NOT NULL,
                setor_id INTEGER,
                objeto TEXT NOT NULL,
                valor REAL DEFAULT 0,
                data_inicio TEXT,
                data_fim TEXT,
                status TEXT DEFAULT 'Ativo',
                observacoes TEXT,
                criado_em TEXT DEFAULT CURRENT_TIMESTAMP, valor_mensal REAL DEFAULT 0, quantidade_meses INTEGER DEFAULT 0,
                FOREIGN KEY (contratante_id) REFERENCES contratante(id),
                FOREIGN KEY (contratado_id) REFERENCES contratado(id),
                FOREIGN KEY (setor_id) REFERENCES setor(id)
            );
CREATE TABLE setor (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                nome TEXT NOT NULL,
                responsavel TEXT,
                nrcelular TEXT,
                criado_em TEXT DEFAULT CURRENT_TIMESTAMP
            , contratante_id INTEGER);
CREATE TABLE usuario (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                nome TEXT NOT NULL,
                login TEXT NOT NULL UNIQUE,
                senha_hash TEXT NOT NULL,
                perfil TEXT NOT NULL DEFAULT 'operador',
                ativo INTEGER NOT NULL DEFAULT 1,
                criado_em TEXT DEFAULT CURRENT_TIMESTAMP
            , contratante_id INTEGER, setor_id INTEGER);
DELETE FROM "sqlite_sequence";
COMMIT;
